+    /// Returns notifications added after the given timestamp.
+    /// Randomly generates a new notification ~30% of the time to simulate real activity.
+    /// </summary>
+    public List<Notification> GetNewSince(DateTime since)
+    {
+        lock (_lock)
+        {
+            if (Random.Shared.NextDouble() < 0.3)
+            {
+                var messages = new[]
+                {
+                    "You have a new follower!",
+                    "Someone commented on your post.",
+                    "System maintenance scheduled for tonight.",
+                    "Your export is ready to download.",
+                    "A team member mentioned you in a discussion.",
+                    "Weekly summary report is available."
+                };
+
+                var msg = messages[Random.Shared.Next(messages.Length)];
+                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
+            }
+
+            return _notifications.Where(n => n.Timestamp > since).ToList();
+        }
